expr:
return {
        kind: 'if',
        line: ifLine,
        endLine: ifLine,
        ifLine,
        predicate,
        // biome-ignore lint/suspicious/noThenProperty: GoIfStmt.then is the if-then body array, not a Promise.then.
        then: [],
        elseIfs: [],
        text: '',
      };

return {
        kind: 'if',
        line: ifLine,
        endLine: Math.max(endLine, ifLine),
        ifLine,
        predicate,
        // biome-ignore lint/suspicious/noThenProperty: GoIfStmt.then is the if-then body array, not a Promise.then.
        then: [],
        elseIfs: [],
        text: predicate,
      };

return {
      kind: 'switch',
      line: switchLine,
      endLine,
      switchLine,
      predicate,
      cases,
      text: predicate,
    };

cases.push({
          line: caseLine,
          ...(predicate !== undefined && predicate !== '' ? { predicate } : {}),
          isDefault,
          body,
        });

return {
      kind: 'return',
      line,
      endLine: this.peek().line,
      ...(text ? { expr: text } : {}),
      ...(callee ? { callee } : {}),
      text,
    };

return {
          kind: 'defer',
          line,
          endLine: blk.closeLine,
          text: '',
          body: blk.stmts,
          hasRecover,
          isFuncLiteral: true,
        };

return {
        kind: 'defer',
        line,
        endLine: line,
        text: '',
        body: [],
        hasRecover: false,
        isFuncLiteral: false,
      };

return {
      kind: 'defer',
      line,
      endLine: this.peek().line,
      text,
      body: [],
      hasRecover: false,
      isFuncLiteral: false,
    };

return {
        kind: 'assign',
        line,
        endLine: Math.max(endLine, line),
        ...(lhs ? { target: lhs } : {}),
        ...(callee ? { callee } : {}),
        text,
      };

return {
        kind: 'assign',
        line,
        endLine: Math.max(endLine, line),
        ...(lhs ? { target: lhs } : {}),
        text,
      };

return {
        kind: 'expr',
        line,
        endLine: Math.max(endLine, line),
        ...(callee ? { callee } : {}),
        text,
      };

return {
          head: chain[0]!,
          tail: chain.slice(1),
          name: chain[chain.length - 1]!,
          line: tk.line,
        };

calls.push({
          head: chain[0]!,
          tail: chain.slice(1),
          name: chain[chain.length - 1]!,
          line,
        });

return {
    imp: { module, name, alias: binding, line },
    next: j,
  };

